from common import *
import numpy as np,pandas as pd
from backtest.scripts.evaluate.eval_ic_multi_pool import summarize_head_series
def main():
    save_source(__file__)
    clf=read(CAMPAIGN/'classifier/metrics/evaluation.json')['primary_predictions'];check(clf)
    pred=pd.read_csv(ROOT/clf['path'],usecols=['date','target_date','predicted_label'],parse_dates=['date','target_date']).set_index('target_date').predicted_label
    ports={};heads={};universe=None
    for v in ['v5',*STYLES]:
        src=PREVEX if v=='v5' else BASE
        panel=pd.read_csv(src/'data'/f'{v}-ensemble-h5-daily.csv',index_col=0,parse_dates=True,float_precision='round_trip');ports[v]=panel.port
        if universe is None:universe=panel.bench
        else:assert panel.bench.equals(universe)
        heads[v]={pd.Timestamp(k):frozenset(z) for k,z in read(src/'data'/f'{v}-formal-heads.json')['ensemble']['3'].items()}
    date=universe.index;oracle=day_labels().reindex(date);forecast=pred.reindex(date).fillna('v5');ctrl=pd.Series('v5',index=date)
    assert len(date)==1448 and forecast.eq('v5').sum()==1 and oracle.notna().all()
    metrics={};matrix=pd.crosstab(oracle,forecast)
    for name,r in [('v5',ctrl),('predicted',forecast),('oracle',oracle)]:
        p=pd.Series([ports[v].loc[d] for d,v in r.items()],index=date)
        h={d:heads[v][d] for d,v in r.items()}
        cuts={'all':pd.Series(True,index=date),**{v:oracle.eq(v) for v in STYLES},'correct':oracle.eq(forecast),'wrong_or_no_forecast':oracle.ne(forecast)}
        summary={}
        for lab,mask in cuts.items():
            z=summarize_head_series((p-universe)[mask],5,sets=h,k=3,turnover_days=set(date[mask]),port=p[mask],bench=universe[mask])
            summary[lab]={k:z.get(k) for k in ['net_ann','net_sharpe','n_days','turnover']}
        metrics[name]=summary
    assert abs(metrics['v5']['all']['net_ann']-read(PREVEX/'metrics/v5.json')['pools']['all']['ensemble']['head']['3']['5']['net_ann'])<1e-12
    write(BASE/'metrics/routing-diagnostic.json',dict(scope='Post-hoc model Top3/H5 return proxy using real head sets and full t-5 turnover. Oracle true weekly style only an explanatory ceiling comparator; never used in executed strategy. Accuracy here includes first fallback and cut to 1448 signal dates, unlike classifier report.',metrics=metrics,counts_by_true_and_predicted_style=matrix.to_dict(),correct_dates=int(oracle.eq(forecast).sum())))
if __name__=='__main__':main()
